/*
 * 1:1 port of opencode's Avatar (`@opencode/ui/avatar`, MIT):
 * packages/ui/src/data-display/avatar/avatar.css.
 *
 * Only the root selector changed, to meet ui-sdk's markup. Every value is
 * upstream: the 16 / 20 / 28px boxes, the circular and 4 / 6px radii, the
 * 0.5px border and the ::before sheen.
 *
 *   [data-component="avatar-v2"]  →  [data-slot="avatar"]  (ui-sdk's root slot)
 *   [data-slot="avatar-image"]    →  same name (ui-sdk already uses it)
 *
 * `data-size` ("small" | "normal" | "large") and `data-kind` ("user" | "org")
 * come from Kitsaas' props; `data-has-image` is upstream's own attribute,
 * exposed as the `hasImage` prop, and drops the sheen once an image is there.
 *
 * Upstream has no [data-color-scheme="dark"] block: the fallback layer,
 * text, border and light-alpha sheen all come from --v2-* tokens that flip
 * with the scheme on their own.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@layer components {
  [data-slot="avatar"] {
    --avatar-bg: var(--v2-background-bg-layer-02);
    --avatar-fg: var(--v2-text-text-muted);
    --avatar-radius: 9999px;
    --avatar-font-size: 11px;
    --avatar-tracking: 0.05px;

    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    position: relative;
    overflow: hidden;
    width: 28px;
    height: 28px;
    border-radius: var(--avatar-radius);
    border: 0.5px solid var(--v2-border-border-base);
    font-weight: 530;
    font-size: var(--avatar-font-size);
    line-height: 1;
    letter-spacing: var(--avatar-tracking);
    text-transform: uppercase;
    background-color: var(--avatar-bg);
    color: var(--avatar-fg);
    user-select: none;
    -webkit-user-select: none;
  }

  [data-slot="avatar"]::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
      180deg,
      var(--v2-alpha-light-16) 0%,
      var(--v2-alpha-light-0) 100%
    );
    pointer-events: none;
  }

  [data-slot="avatar"][data-has-image]::before {
    display: none;
  }

  [data-slot="avatar"][data-kind="org"] {
    --avatar-radius: 6px;
  }

  [data-slot="avatar"][data-kind="org"][data-size="normal"],
  [data-slot="avatar"][data-kind="org"][data-size="small"] {
    --avatar-radius: 4px;
  }

  [data-slot="avatar"][data-size="normal"] {
    width: 20px;
    height: 20px;
  }

  [data-slot="avatar"][data-size="small"] {
    width: 16px;
    height: 16px;
  }

  [data-slot="avatar"] [data-slot="avatar-image"] {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    border-radius: inherit;
    user-select: none;
    -webkit-user-select: none;
    -webkit-user-drag: none;
  }
}
